{
  "items": [
    {
      "name": "DFinsupp.sum_neg_index",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → AddGroup (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_3 : AddCommMonoid γ] {g : Π₀ (i : ι), β i}\n  {h : (i : ι) → β i → γ}, (∀ (i : ι), h i 0 = 0) → (-g).sum h = g.sum fun i b => h i (-b)"
    },
    {
      "name": "DFinsupp.sum_neg",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → AddCommMonoid (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_3 : SubtractionCommMonoid γ] {f : Π₀ (i : ι), β i}\n  {h : (i : ι) → β i → γ}, (f.sum fun i b => -h i b) = -f.sum h"
    },
    {
      "name": "Finsupp.sum_neg",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {G : Type u_12} [inst : Zero M] [inst_1 : AddCommGroup G] {f : α →₀ M} {h : α → M → G},\n  (f.sum fun a b => -h a b) = -f.sum h"
    },
    {
      "name": "Finsupp.sum_neg_index",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {G : Type u_12} [inst : SubtractionMonoid G] [inst_1 : AddCommMonoid M] {g : α →₀ G}\n  {h : α → G → M}, (∀ (a : α), h a 0 = 0) → (-g).sum h = g.sum fun a b => h a (-b)"
    },
    {
      "name": "Finset.sum_neg_index",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Finset.BigOperators",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Type u_2} [inst : AddCommMonoid α] [inst_1 : DecidableEq ι] [inst_2 : InvolutiveNeg ι]\n  (s : Finset ι) (f : ι → α), ∑ i ∈ -s, f i = ∑ i ∈ s, f (-i)"
    },
    {
      "name": "Finset.sum_neg_distrib",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {G : Type u_5} {s : Finset ι} [inst : SubtractionCommMonoid G] (f : ι → G),\n  ∑ x ∈ s, -f x = -∑ x ∈ s, f x"
    }
  ]
}

